import{_ as i,a0 as s,w as r,s as p,ao as n,I as l,a1 as d,A as t,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Cloud Commander：一個有控制台和編輯器的 Web 文件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"Cloud Commander：一個有控制台和編輯器的 Web 文件管理器 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cloud Commander：一個有控制台和編輯器的 Web 文件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cloud Commander：一個有控制台和編輯器的 Web 文件管理器 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20160503 Cloud Commander - A Web File Manager With Console And Editor","title":"Cloud Commander：一個有控制台和編輯器的 Web 文件管理器","tag":"201809","desc":""},"relativePath":"201809/20160503 Cloud Commander - A Web File Manager With Console And Editor.md","filePath":"[post].md"}'),m={name:"201809/20160503 Cloud Commander - A Web File Manager With Console And Editor.md"};function u(h,o,c,C,g,b){const a=s("Link");return r(),p("div",null,[o[16]||(o[16]=n('<h1 id="cloud-commander-一個有控制台和編輯器的-web-文件管理器" tabindex="-1">Cloud Commander：一個有控制台和編輯器的 Web 文件管理器 <a class="header-anchor" href="#cloud-commander-一個有控制台和編輯器的-web-文件管理器" aria-label="Permalink to “Cloud Commander：一個有控制台和編輯器的 Web 文件管理器”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/05/Cloud-Commander-A-Web-File-Manager-With-Console-And-Editor-720x340.png" alt=""></p><p><strong>Cloud Commander</strong> 是一個基於 web 的文件管理程序，它允許你通過任何計算機、移動端或平板電腦的瀏覽器查看、訪問或管理系統文件或文件夾。它有兩個簡單而又經典的面板，並且會像你設備的顯示尺寸一樣自動轉換大小。它也擁有兩款內置的叫做 <strong>Dword</strong> 和 <strong>Edward</strong> 的文本編輯器，它們支持語法高亮，並帶有一個支持系統命令列的控制台。因此，您可以隨時隨地編輯文件。Cloud Commander 服務器是一款在 Linux、Windows、Mac OS X 運行的跨平台應用，而且該應用客户端可以在任何一款瀏覽器上運行。它是用 <strong>JavaScript/Node.Js</strong> 寫的，並使用 <strong>MIT</strong> 許可證。</p><p>在這個簡易教程中，讓我們看一看如何在 Ubuntu 18.04 LTS 服務器上安裝 Cloud Commander。</p><h3 id="前提條件" tabindex="-1">前提條件 <a class="header-anchor" href="#前提條件" aria-label="Permalink to “前提條件”">​</a></h3><p>像我之前提到的，是用 Node.js 寫的。所以為了安裝 Cloud Commander，我們需要首先安裝 Node.js。要執行安裝，參考下面的指南。</p>',6)),l("ul",null,[l("li",null,[d(a,{href:"https://www.ostechnix.com/install-node-js-linux/"},{default:t(()=>[...o[0]||(o[0]=[e("如何在 Linux 上安裝 Node.js",-1)])]),_:1})])]),o[17]||(o[17]=n('<h3 id="安裝-cloud-commander" tabindex="-1">安裝 Cloud Commander <a class="header-anchor" href="#安裝-cloud-commander" aria-label="Permalink to “安裝 Cloud Commander”">​</a></h3><p>在安裝 Node.js 之後，運行下列命令安裝 Cloud Commander:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ npm i cloudcmd -g</span></span></code></pre></div><p>祝賀！Cloud Commander 已經安裝好了。讓我們往下繼續看看 Cloud Commander 的基本使用。</p><h3 id="開始使用-cloud-commander" tabindex="-1">開始使用 Cloud Commander <a class="header-anchor" href="#開始使用-cloud-commander" aria-label="Permalink to “開始使用 Cloud Commander”">​</a></h3><p>運行以下命令啓動 Cloud Commander：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cloudcmd</span></span></code></pre></div><p><strong>輸出示例：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>url: http://localhost:8000</span></span></code></pre></div><p>現在，打開你的瀏覽器並轉到鏈接：<code>http://localhost:8000</code> 或 <code>http://IP-address:8000</code>。</p><p>從現在開始，您可以直接在本地系統或遠程系統或移動設備，平板電腦等Web瀏覽器中創建，刪除，查看，管理文件或文件夾。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/Cloud-Commander-Google-Chrome_006-4.jpg" alt=""></p><p>如你所見上面的截圖，Clouder Commander 有兩個面板，十個熱鍵 （<code>F1</code> 到 <code>F10</code>），還有控制台。</p><p>每個熱鍵執行的都是一個任務。</p><ul><li><code>F1</code> – 幫助</li><li><code>F2</code> – 重命名文件/文件夾</li><li><code>F3</code> – 查看文件/文件夾</li><li><code>F4</code> – 編輯文件</li><li><code>F5</code> – 複製文件/文件夾</li><li><code>F6</code> – 移動文件/文件夾</li><li><code>F7</code> – 創建新目錄</li><li><code>F8</code> – 刪除文件/文件夾</li><li><code>F9</code> – 打開菜單</li><li><code>F10</code> – 打開設置</li></ul><h4 id="cloud-commmander-控制台" tabindex="-1">Cloud Commmander 控制台 <a class="header-anchor" href="#cloud-commmander-控制台" aria-label="Permalink to “Cloud Commmander 控制台”">​</a></h4><p>點擊控制台圖標。這即將打開系統默認的命令列界面。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/Cloud-Commander-Google-Chrome_007-2.jpg" alt=""></p><p>在此控制台中，您可以執行各種管理任務，例如安裝軟件包、刪除軟件包、更新系統等。您甚至可以關閉或重新引導系統。 因此，Cloud Commander 不僅僅是一個文件管理器，還具有遠程管理工具的功能。</p><h4 id="創建文件-文件夾" tabindex="-1">創建文件/文件夾 <a class="header-anchor" href="#創建文件-文件夾" aria-label="Permalink to “創建文件/文件夾”">​</a></h4><p>要創建新的文件或文件夾就右鍵單擊任意空位置並找到 “New - &gt;File or Directory”。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/Cloud-commander-file-folder-1.png" alt=""></p><h4 id="查看文件" tabindex="-1">查看文件 <a class="header-anchor" href="#查看文件" aria-label="Permalink to “查看文件”">​</a></h4><p>你可以查看圖片，查看音視頻文件。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/Cloud-Commander-home-sk-Google-Chrome_008-1.jpg" alt=""></p><h4 id="上傳文件" tabindex="-1">上傳文件 <a class="header-anchor" href="#上傳文件" aria-label="Permalink to “上傳文件”">​</a></h4><p>另一個很酷的特性是我們可以從任何系統或設備簡單地上傳一個文件到 Cloud Commander 系統。</p><p>要上傳文件，右鍵單擊 Cloud Commander 面板的任意空白處，並且單擊“Upload”選項。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/cloud-commander-upload-2.png" alt=""></p><p>選擇你想要上傳的文件。</p><p>另外，你也可以上傳來自像 Google 雲盤、Dropbox、Amazon 雲盤、Facebook、Twitter、Gmail、GitHub、Picasa、Instagram 還有很多的雲服務上的文件。</p><p>要從雲端上傳文件, 右鍵單擊面板的任意空白處，並且右鍵單擊面板任意空白處並選擇“Upload from Cloud”。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/upload-from-cloud-1.png" alt=""></p><p>選擇任意一個你選擇的網絡服務，例如谷歌雲盤。點擊“Connect to Google drive”按鈕。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/Cloud-Commander-home-sk-Google-Chrome_009-2.jpg" alt=""></p><p>下一步，用 Cloud Commander 驗證你的谷歌雲端硬盤，從谷歌雲端硬盤選擇文件並點擊“Upload”。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/05/Cloud-Commander-home-sk-Google-Chrome_010-1.jpg" alt=""></p><h4 id="更新-cloud-commander" tabindex="-1">更新 Cloud Commander <a class="header-anchor" href="#更新-cloud-commander" aria-label="Permalink to “更新 Cloud Commander”">​</a></h4><p>要更新到最新的可用版本，執行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ npm update cloudcmd -g</span></span></code></pre></div><h4 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h4><p>據我測試，它運行很好。在我的 Ubuntu 服務器測試期間，我沒有遇到任何問題。此外，Cloud Commander 不僅是基於 Web 的文件管理器，還可以充當執行大多數 Linux 管理任務的遠程管理工具。 您可以創建文件/文件夾、重命名、刪除、編輯和查看它們。此外，您可以像在終端中在本地系統中那樣安裝、更新、升級和刪除任何軟件包。當然，您甚至可以從 Cloud Commander 控制台本身關閉或重啓系統。 還有什麼需要的嗎？ 嘗試一下，你會發現它很有用。</p><p>目前為止就這樣吧。 我將很快在這裏發表另一篇有趣的文章。 在此之前，請繼續關注我們。</p><p>祝賀！</p><hr>',45)),l("p",null,[o[2]||(o[2]=e("via: ",-1)),d(a,{href:"https://www.ostechnix.com/cloud-commander-a-web-file-manager-with-console-and-editor/"},{default:t(()=>[...o[1]||(o[1]=[e("https://www.ostechnix.com/cloud-commander-a-web-file-manager-with-console-and-editor/",-1)])]),_:1})]),l("p",null,[o[7]||(o[7]=e("作者：",-1)),d(a,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...o[3]||(o[3]=[e("SK",-1)])]),_:1}),o[8]||(o[8]=e(" 選題：",-1)),d(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...o[4]||(o[4]=[e("lujun9972",-1)])]),_:1}),o[9]||(o[9]=e(" 譯者：",-1)),d(a,{href:"https://github.com/fuzheng1998"},{default:t(()=>[...o[5]||(o[5]=[e("fuzheng1998",-1)])]),_:1}),o[10]||(o[10]=e(" 校對：",-1)),d(a,{href:"https://github.com/wxy"},{default:t(()=>[...o[6]||(o[6]=[e("wxy",-1)])]),_:1})]),l("p",null,[o[13]||(o[13]=e("本文由 ",-1)),d(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...o[11]||(o[11]=[e("LCTT",-1)])]),_:1}),o[14]||(o[14]=e(" 原創編譯，",-1)),d(a,{href:"https://linux.cn/"},{default:t(()=>[...o[12]||(o[12]=[e("Linux中國",-1)])]),_:1}),o[15]||(o[15]=e(" 榮譽推出",-1))])])}const x=i(m,[["render",u]]);export{k as __pageData,x as default};
